/// Audio sample formats
///
/// - The data described by the sample format is always in native-endian order.
/// Sample values can be expressed by native C types, hence the lack of a signed
/// 24-bit sample format even though it is a common raw audio data format.
///
/// - The floating-point formats are based on full volume being in the range
/// [-1.0, 1.0]. Any values outside this range are beyond full volume level.
///
/// - The data layout as used in av_samples_fill_arrays() and elsewhere in FFmpeg
/// (such as AVFrame in libavcodec) is as follows:
///
/// @par
/// For planar sample formats, each audio channel is in a separate data plane,
/// and linesize is the buffer size, in bytes, for a single plane. All data
/// planes must be the same size. For packed sample formats, only the first data
/// plane is used, and samples for each channel are interleaved. In this case,
/// linesize is the buffer size, in bytes, for the 1 plane.
enum AVSampleFormat {
  AV_SAMPLE_FMT_NONE(-1),

  /// < unsigned 8 bits
  AV_SAMPLE_FMT_U8(0),

  /// < signed 16 bits
  AV_SAMPLE_FMT_S16(1),

  /// < signed 32 bits
  AV_SAMPLE_FMT_S32(2),

  /// < float
  AV_SAMPLE_FMT_FLT(3),

  /// < double
  AV_SAMPLE_FMT_DBL(4),

  /// < unsigned 8 bits, planar
  AV_SAMPLE_FMT_U8P(5),

  /// < signed 16 bits, planar
  AV_SAMPLE_FMT_S16P(6),

  /// < signed 32 bits, planar
  AV_SAMPLE_FMT_S32P(7),

  /// < float, planar
  AV_SAMPLE_FMT_FLTP(8),

  /// < double, planar
  AV_SAMPLE_FMT_DBLP(9),

  /// < signed 64 bits
  AV_SAMPLE_FMT_S64(10),

  /// < signed 64 bits, planar
  AV_SAMPLE_FMT_S64P(11),

  /// < Number of sample formats. DO NOT USE if linking dynamically
  AV_SAMPLE_FMT_NB(12);

  final int value;
  const AVSampleFormat(this.value);

  static AVSampleFormat fromValue(int value) => switch (value) {
    -1 => AV_SAMPLE_FMT_NONE,
    0 => AV_SAMPLE_FMT_U8,
    1 => AV_SAMPLE_FMT_S16,
    2 => AV_SAMPLE_FMT_S32,
    3 => AV_SAMPLE_FMT_FLT,
    4 => AV_SAMPLE_FMT_DBL,
    5 => AV_SAMPLE_FMT_U8P,
    6 => AV_SAMPLE_FMT_S16P,
    7 => AV_SAMPLE_FMT_S32P,
    8 => AV_SAMPLE_FMT_FLTP,
    9 => AV_SAMPLE_FMT_DBLP,
    10 => AV_SAMPLE_FMT_S64,
    11 => AV_SAMPLE_FMT_S64P,
    12 => AV_SAMPLE_FMT_NB,
    _ => throw ArgumentError('Unknown value for AVSampleFormat: $value'),
  };
}

