enum SwsBackend {
  /// < Legacy bespoke format-specific code
  SWS_BACKEND_LEGACY(1),

  /// < Template-based C reference implementation
  SWS_BACKEND_C(2),

  /// < Fast path using libc memcpy() / memset()
  SWS_BACKEND_MEMCPY(4),

  /// < Chained x86 SIMD kernels
  SWS_BACKEND_X86(8),

  /// < Chained AArch64 NEON kernels
  SWS_BACKEND_AARCH64(16),

  /// < Vulkan SPIR-V backend
  SWS_BACKEND_SPIRV(32),
  SWS_BACKEND_UNSTABLE(62),
  SWS_BACKEND_ALL(63),

  /// < force size to 32 bits, not a valid backend
  SWS_BACKEND_MAX_ENUM(2147483647);

  static const SWS_BACKEND_STABLE = SWS_BACKEND_LEGACY;

  final int value;
  const SwsBackend(this.value);

  static SwsBackend fromValue(int value) => switch (value) {
    1 => SWS_BACKEND_LEGACY,
    2 => SWS_BACKEND_C,
    4 => SWS_BACKEND_MEMCPY,
    8 => SWS_BACKEND_X86,
    16 => SWS_BACKEND_AARCH64,
    32 => SWS_BACKEND_SPIRV,
    62 => SWS_BACKEND_UNSTABLE,
    63 => SWS_BACKEND_ALL,
    2147483647 => SWS_BACKEND_MAX_ENUM,
    _ => throw ArgumentError('Unknown value for SwsBackend: $value'),
  };

  @override
  String toString() {
    if (this == SWS_BACKEND_LEGACY)
      return "SwsBackend.SWS_BACKEND_LEGACY, SwsBackend.SWS_BACKEND_STABLE";
    return super.toString();
  }
}

enum SwsFlags {
  /// Return an error on underspecified conversions. Without this flag,
  /// unspecified fields are defaulted to sensible values.
  SWS_STRICT(2048),

  /// Emit verbose log of scaling parameters.
  SWS_PRINT_INFO(4096),

  /// Perform full chroma upsampling when upscaling to RGB.
  ///
  /// For example, when converting 50x50 yuv420p to 100x100 rgba, setting this flag
  /// will scale the chroma plane from 25x25 to 100x100 (4:4:4), and then convert
  /// the 100x100 yuv444p image to rgba in the final output step.
  ///
  /// Without this flag, the chroma plane is instead scaled to 50x100 (4:2:2),
  /// with a single chroma sample being reused for both of the horizontally
  /// adjacent RGBA output pixels.
  SWS_FULL_CHR_H_INT(8192),

  /// Perform full chroma interpolation when downscaling RGB sources.
  ///
  /// For example, when converting a 100x100 rgba source to 50x50 yuv444p, setting
  /// this flag will generate a 100x100 (4:4:4) chroma plane, which is then
  /// downscaled to the required 50x50.
  ///
  /// Without this flag, the chroma plane is instead generated at 50x100 (dropping
  /// every other pixel), before then being downscaled to the required 50x50
  /// resolution.
  SWS_FULL_CHR_H_INP(16384),

  /// Force bit-exact output. This will prevent the use of platform-specific
  /// optimizations that may lead to slight difference in rounding, in favor
  /// of always maintaining exact bit output compatibility with the reference
  /// C code.
  ///
  /// Note: It is recommended to set both of these flags simultaneously.
  SWS_ACCURATE_RND(262144),
  SWS_BITEXACT(524288),

  /// Allow/prefer using experimental new code paths. This may be faster,
  /// slower, or produce different output, with semantics subject to change
  /// at any point in time. For testing and debugging purposes only.
  SWS_UNSTABLE(1048576),

  /// < This flag has no effect
  SWS_DIRECT_BGR(32768),

  /// < Set `SwsContext.dither` instead
  SWS_ERROR_DIFFUSION(8388608),

  /// < fast bilinear filtering
  SWS_FAST_BILINEAR(1),

  /// < bilinear filtering
  SWS_BILINEAR(2),

  /// < 2-tap cubic B-spline
  SWS_BICUBIC(4),

  /// < experimental
  SWS_X(8),

  /// < nearest neighbor
  SWS_POINT(16),

  /// < area averaging
  SWS_AREA(32),

  /// < bicubic luma, bilinear chroma
  SWS_BICUBLIN(64),

  /// < gaussian approximation
  SWS_GAUSS(128),

  /// < unwindowed sinc
  SWS_SINC(256),

  /// < 3-tap sinc/sinc
  SWS_LANCZOS(512),

  /// < unwindowed natural cubic spline
  SWS_SPLINE(1024);

  final int value;
  const SwsFlags(this.value);

  static SwsFlags fromValue(int value) => switch (value) {
    2048 => SWS_STRICT,
    4096 => SWS_PRINT_INFO,
    8192 => SWS_FULL_CHR_H_INT,
    16384 => SWS_FULL_CHR_H_INP,
    262144 => SWS_ACCURATE_RND,
    524288 => SWS_BITEXACT,
    1048576 => SWS_UNSTABLE,
    32768 => SWS_DIRECT_BGR,
    8388608 => SWS_ERROR_DIFFUSION,
    1 => SWS_FAST_BILINEAR,
    2 => SWS_BILINEAR,
    4 => SWS_BICUBIC,
    8 => SWS_X,
    16 => SWS_POINT,
    32 => SWS_AREA,
    64 => SWS_BICUBLIN,
    128 => SWS_GAUSS,
    256 => SWS_SINC,
    512 => SWS_LANCZOS,
    1024 => SWS_SPLINE,
    _ => throw ArgumentError('Unknown value for SwsFlags: $value'),
  };
}

enum SwsIntent {
  /// < Perceptual tone mapping
  SWS_INTENT_PERCEPTUAL(0),

  /// < Relative colorimetric clipping
  SWS_INTENT_RELATIVE_COLORIMETRIC(1),

  /// < Saturation mapping
  SWS_INTENT_SATURATION(2),

  /// < Absolute colorimetric clipping
  SWS_INTENT_ABSOLUTE_COLORIMETRIC(3),

  /// < not part of the ABI
  SWS_INTENT_NB(4);

  final int value;
  const SwsIntent(this.value);

  static SwsIntent fromValue(int value) => switch (value) {
    0 => SWS_INTENT_PERCEPTUAL,
    1 => SWS_INTENT_RELATIVE_COLORIMETRIC,
    2 => SWS_INTENT_SATURATION,
    3 => SWS_INTENT_ABSOLUTE_COLORIMETRIC,
    4 => SWS_INTENT_NB,
    _ => throw ArgumentError('Unknown value for SwsIntent: $value'),
  };
}

/// Main external API structure. New fields can be added to the end with
/// minor version bumps. Removal, reordering and changes to existing fields
/// require a major version bump. sizeof(SwsContext) is not part of the ABI.
final class SwsContext extends ffi.Struct {
  external ffi.Pointer<AVClass> av_class;

  /// Private data of the user, can be used to carry app specific stuff.
  external ffi.Pointer<ffi.Void> opaque;

  /// Bitmask of SWS_*. See `SwsFlags` for details.
  @ffi.UnsignedInt()
  external int flags;

  @ffi.Array.multi([2])
  external ffi.Array<ffi.Double> scaler_params;

  /// How many threads to use for processing, or 0 for automatic selection.
  @ffi.Int()
  external int threads;

  /// Dither mode.
  @ffi.UnsignedInt()
  external int ditherAsInt;

  SwsDither get dither => SwsDither.fromValue(ditherAsInt);

  /// Alpha blending mode. See `SwsAlphaBlend` for details.
  @ffi.UnsignedInt()
  external int alpha_blendAsInt;

  SwsAlphaBlend get alpha_blend => SwsAlphaBlend.fromValue(alpha_blendAsInt);

  /// Use gamma correct scaling.
  @ffi.Int()
  external int gamma_flag;

  /// < Width and height of the source frame
  @ffi.Int()
  external int src_w;

  @ffi.Int()
  external int src_h;

  /// < Width and height of the destination frame
  @ffi.Int()
  external int dst_w;

  @ffi.Int()
  external int dst_h;

  /// < Source pixel format
  @ffi.Int()
  external int src_format;

  /// < Destination pixel format
  @ffi.Int()
  external int dst_format;

  /// < Source is full range
  @ffi.Int()
  external int src_range;

  /// < Destination is full range
  @ffi.Int()
  external int dst_range;

  /// < Source vertical chroma position in luma grid / 256
  @ffi.Int()
  external int src_v_chr_pos;

  /// < Source horizontal chroma position
  @ffi.Int()
  external int src_h_chr_pos;

  /// < Destination vertical chroma position
  @ffi.Int()
  external int dst_v_chr_pos;

  /// < Destination horizontal chroma position
  @ffi.Int()
  external int dst_h_chr_pos;

  /// Desired ICC intent for color space conversions.
  @ffi.Int()
  external int intent;

  /// Scaling filter. If set to something other than SWS_SCALE_AUTO, this will
  /// override the filter implied by `SwsContext.flags`.
  ///
  /// Note: Does not affect the legacy (stateful) API.
  @ffi.UnsignedInt()
  external int scalerAsInt;

  SwsScaler get scaler => SwsScaler.fromValue(scalerAsInt);

  /// Scaler used specifically for up/downsampling subsampled (chroma) planes.
  /// If set to something other than SWS_SCALE_AUTO, this will override the
  /// filter implied by `SwsContext.scaler`. Otherwise, the same filter
  /// will be used for both main scaling and chroma subsampling.
  @ffi.UnsignedInt()
  external int scaler_subAsInt;

  SwsScaler get scaler_sub => SwsScaler.fromValue(scaler_subAsInt);

  /// Bitmask of SWS_BACKEND_*. If non-zero, this will restrict the available
  /// backends to the specified set. If left as zero, a default set of
  /// backends will be selected automatically (based on SWS_UNSTABLE).
  ///
  /// Note: This is only relevant for the new API (sws_scale_frame()). The
  /// stateful legacy API always implies SWS_BACKEND_LEGACY.
  @ffi.UnsignedInt()
  external int backendsAsInt;

  SwsBackend get backends => SwsBackend.fromValue(backendsAsInt);
}

/// when used for filters they must have an odd number of elements
/// coeffs cannot be shared between vectors
final class SwsVector extends ffi.Struct {
  /// < pointer to the list of coefficients
  external ffi.Pointer<ffi.Double> coeff;

  /// < number of coefficients in the vector
  @ffi.Int()
  external int length;
}

/// vectors can be shared
final class SwsFilter extends ffi.Struct {
  external ffi.Pointer<SwsVector> lumH;

  external ffi.Pointer<SwsVector> lumV;

  external ffi.Pointer<SwsVector> chrH;

  external ffi.Pointer<SwsVector> chrV;
}

